(()=>{
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n/100);
let register=false,store,user,cart=[],requestKey;SOSProfile.mount($('#registration-profile'));SOSProfile.mount($('#account-profile-fields'));for(const name of ['fullName','cpf','gender','birthDate'])$('#account-profile-fields').querySelector('[name="'+name+'"]').disabled=true;$('#registration-profile').querySelectorAll('input,select,button').forEach(field=>field.disabled=true);
const theme=localStorage.getItem('sos-theme');if(theme)document.documentElement.dataset.theme=theme;$('#member-theme').onclick=()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;localStorage.setItem('sos-theme',next)};
function message(text,error=false){$('#member-message').textContent=text;$('#member-message').className=error?'error':'success'}
async function api(path,body){const r=await fetch(path,{cache:'no-store',...(body?{method:'POST',headers:{'Content-Type':'application/json','X-SOS-Member':'1'},body:JSON.stringify(body)}:{})});const data=await r.json();if(!r.ok)throw Error(data.error||'Não foi possível concluir. Tente novamente.');return data}
function tab(signup){register=signup;$('#member-auth').classList.toggle('register-mode',signup);$('#registration-profile').hidden=!signup;$('#registration-profile').querySelectorAll('input,select,button').forEach(field=>field.disabled=!signup);$('#member-form').elements.password.autocomplete=signup?'new-password':'current-password';$('#member-submit').textContent=signup?'Criar minha conta':'Entrar na minha conta';for(const [id,active] of [['login-tab',!signup],['register-tab',signup]]){$('#'+id).className='button '+(active?'primary':'outline');$('#'+id).setAttribute('aria-pressed',active)}}
$('#login-tab').onclick=()=>tab(false);$('#register-tab').onclick=()=>tab(true);
$('#member-form').onsubmit=async e=>{e.preventDefault();const button=$('#member-submit');button.disabled=true;try{const data=Object.fromEntries(new FormData(e.currentTarget));user=(await api('/api/members/'+(register?'register':'login'),data)).member;e.target.reset();message(register?'Cadastro criado. Bem-vindo!':'Você entrou na sua conta.');await account()}catch(err){message(err.message,true)}finally{button.disabled=false}};
$('#member-logout').onclick=async()=>{try{await api('/api/members/logout',{});user=null;await account();message('Você saiu da conta.')}catch(e){message(e.message,true)}};
$('#profile-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button[type=submit]');button.disabled=true;try{await api('/api/members/profile',Object.fromEntries(new FormData(e.target)));$('#profile-message').textContent='Dados atualizados.'}catch(err){$('#profile-message').textContent=err.message}finally{button.disabled=false}};
async function account(){$('#member-auth').hidden=!!user;$('#member-account').hidden=!user;if(!user)return;$('#member-greeting').textContent='Olá, '+user.name;$('#account-email').value=user.email;await loadOrders();const data=await api('/api/members/profile');SOSProfile.fill($('#account-profile-fields'),data.profile);$('#account-profile').open=!data.profile.cpf;checkout()}
function checkout(){const target=$('#member-checkout');target.hidden=true;if(!new URLSearchParams(location.search).has('checkout'))return;let raw;try{raw=JSON.parse(sessionStorage.getItem('sos-cart')||'[]')}catch{raw=[]}cart=Array.isArray(raw)?raw.map(([id,quantity])=>({product:store.products.find(p=>p.id===id&&p.mode==='cart'),quantity})).filter(x=>x.product&&Number.isInteger(x.quantity)&&x.quantity>0&&x.quantity<=10):[];if(!cart.length)return;target.hidden=false;target.innerHTML='<h2>Confirmar meu pedido</h2>'+`<ul class="order-items">${cart.map(x=>`<li><span>${x.quantity} × ${esc(x.product.name)}</span><strong>${money(x.product.price*x.quantity)}</strong></li>`).join('')}</ul><p class="order-total">Total dos produtos: ${money(cart.reduce((n,x)=>n+x.product.price*x.quantity,0))}</p><p class="member-note">${store.settings.demo?'Catálogo em demonstração: este pedido é um teste; as avaliações serão identificadas como demonstração. ':''}Pagamento combinado com a loja pelo WhatsApp. Estoque, entrega, frete e condições serão confirmados pela equipe. Nenhuma cobrança é feita aqui.</p><button id="place-order" class="button primary">${store.settings.demo?'Registrar pedido de demonstração':'Enviar pedido à loja'}</button>`;
if(!requestKey)requestKey=sessionStorage.getItem('sos-order-request')||crypto.randomUUID();sessionStorage.setItem('sos-order-request',requestKey);
$('#place-order').onclick=async e=>{e.target.disabled=true;try{const result=await api('/api/members/orders',{requestKey,items:cart.map(x=>({id:x.product.id,quantity:x.quantity}))});sessionStorage.removeItem('sos-cart');sessionStorage.removeItem('sos-order-request');requestKey=null;target.hidden=true;message('Pedido '+result.id.slice(0,8)+' registrado. Combine o pagamento com a loja pelo link do pedido.');await loadOrders()}catch(err){message(err.message,true);e.target.disabled=false}}}
async function loadOrders(){const {orders,reviews}=await api('/api/members/orders');$('#member-orders').innerHTML=orders.length?orders.map(o=>`<article class="member-card"><div class="order-heading"><h3>Pedido ${esc(o.id.slice(0,8))}</h3><span class="order-status">${o.demo?'Demonstração · ':''}${({pending:'Aguardando confirmação',completed:'Concluído',cancelled:'Cancelado'})[o.status]}</span></div><small>${new Date(o.createdAt).toLocaleString('pt-BR')}</small><ul class="order-items">${o.items.map(p=>`<li><a href="produto.html?id=${encodeURIComponent(p.id)}">${p.quantity} × ${esc(p.name)}</a><strong>${money(p.quantity*p.price)}</strong></li>`).join('')}</ul><p class="order-total">Total dos produtos: ${money(o.total)}</p>${o.status==='pending'?`<p class="member-note">A loja confirmará disponibilidade, pagamento e entrega.</p><a class="button outline" href="https://wa.me/${store.settings.phone}?text=${encodeURIComponent('Olá! Quero combinar pagamento e entrega do pedido '+o.id)}" target="_blank" rel="noopener">Falar sobre este pedido</a>`:''}${o.status==='completed'?o.items.map(p=>reviews.some(r=>r.productId===p.id)?`<p class="member-note">Você já avaliou ${esc(p.name)}.</p>`:`<details class="member-review"><summary>Avaliar ${esc(p.name)}</summary><form data-review="${esc(p.id)}"><label>Nota<select name="rating" required><option value="">Selecione</option>${[5,4,3,2,1].map(n=>`<option value="${n}">${n} estrela${n>1?'s':''}</option>`).join('')}</select></label><label>Sua avaliação<textarea name="text" required minlength="3" maxlength="600" placeholder="Como foi sua experiência com o produto?"></textarea></label><small>Sua avaliação e seu nome completo ficarão públicos na página do produto.</small><button class="button primary">Publicar avaliação</button></form></details>`).join(''):''}</article>`).join(''):'<div class="member-card"><h3>Seu primeiro pedido começa aqui.</h3><p class="member-note">Escolha seus produtos no catálogo e finalize pela sua conta.</p><a class="button primary" href="produtos.html">Explorar produtos</a></div>';
document.querySelectorAll('[data-review]').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button');button.disabled=true;try{await api('/api/members/reviews',{productId:form.dataset.review,rating:Number(form.elements.rating.value),text:form.elements.text.value});await loadOrders();message('Avaliação publicada na página do produto. Obrigado!')}catch(err){message(err.message,true);button.disabled=false}})}
Promise.all([api('/api/catalog'),api('/api/members/session')]).then(async([catalog,session])=>{store=catalog;user=session.member;await account()}).catch(e=>message(e.message,true));
})();
